for(const t of data.topics)for(const label of [t.key,t.label,t.parent,...t.aliases]){const n=norm(label);if(priorNames.has(n)||protectedNames.has(n)||base.resolve(label)||index.has(n)&&index.get(n).key!==t.key)throw Error('First-aid name collision: '+label);index.set(n,t);}
