function audit(){const prior=base.audit(),issues=[...(prior.issues||[])];if(topics.length!==216||new Set(topics.map(t=>t.key)).size!==216)issues.push('first-aid-card-count');for(const t of data.topics){const r=build({diagnosis:t.key,age:'unknown',reviewed:false});if(!r.ok||r.topic!==t.key||r.sections.length!==5||r.refs.some(id=>!sources[id]))issues.push('first-aid-body:'+t.key);}return {...prior,ok:!issues.length,issues,topics:topics.length,urgent:topics.filter(t=>t.urgency).length,firstAid:{newCards:3,newControls:0,fullCoverageVerified:false}};}
